<!-- Problem detail shell with practice history. -->
<script setup lang="ts">
import { onMounted } from 'vue'; import { useRoute } from 'vue-router'; import { api } from '../api'; import { usePracticeRecordStore } from '../stores/practiceRecord'; import type { ProblemListItem } from '../types';
const route = useRoute(); const id = String(route.params.problemId); const records = usePracticeRecordStore(); let problem: ProblemListItem | null = null; let error = ''; let loading = true;
onMounted(async () => { try { const response = await api.get<{ data: ProblemListItem }>(`/problems/${id}`); problem = response.data.data; await records.fetch(id); } catch (cause: unknown) { error = cause instanceof Error ? cause.message : '题目加载失败'; } finally { loading = false; } });
</script>
<template><section class="p-5 md:p-8"><p v-if="loading" role="status">正在加载题目…</p><p v-else-if="error" role="alert">{{ error }}</p><template v-else><h2 class="text-2xl font-semibold">{{ problem?.title }}</h2><div class="mt-8"><h3 class="mb-3 font-semibold">练习记录</h3><p v-if="records.loading">正在加载记录…</p><p v-else-if="records.error" role="alert">{{ records.error }}</p><p v-else-if="!records.items.length">还没有练习记录。</p><ul v-else class="space-y-2"> <li v-for="record in records.items" :key="record.id" class="border border-[var(--color-border)] p-3 text-sm"><span>{{ record.practicedAt }}</span><span class="ml-4" :class="record.solvedFirstTry ? 'text-[var(--color-accent)]' : 'text-[var(--color-text)]/70'">{{ record.solvedFirstTry ? '一遍做对' : '未一遍做对' }}</span><p v-if="record.remark" class="mt-1 text-[var(--color-text)]/70">{{ record.remark }}</p></li></ul></div></template></section></template>
